<x-layouts.public title="Permission record | IRDI" :noindex="true"><section class="mx-auto max-w-3xl space-y-5 px-6 py-12"><h1 class="text-3xl font-bold">Permission record</h1><p>IRDI records the landowner response but does not itself grant access. Verify permission before each visit.</p><dl class="space-y-3"><dt>Property</dt><dd>{{ $permission->property_label }}</dd><dt>Landowner email</dt><dd>{{ $permission->landowner_email }}</dd><dt>Status</dt><dd>{{ ucfirst($permission->effectiveStatus()) }}</dd><dt>Dates</dt><dd>{{ $permission->starts_on->toDateString() }} — {{ $permission->ends_on->toDateString() }}</dd><dt>Activity</dt><dd class="whitespace-pre-wrap">{{ $permission->proposed_activity }}</dd><dt>Requested conditions</dt><dd class="whitespace-pre-wrap">{{ $permission->requested_conditions }}</dd><dt>Landowner conditions</dt><dd class="whitespace-pre-wrap">{{ $permission->landowner_conditions }}</dd><dt>Response timestamp (UTC)</dt><dd>{{ $permission->responded_at?->toDateTimeString() ?? 'Not yet responded' }}</dd><dt>Withdrawal timestamp (UTC)</dt><dd>{{ $permission->withdrawn_at?->toDateTimeString() ?? 'Not withdrawn' }}</dd></dl><button onclick="window.print()" class="rounded border p-3 print:hidden">Print record</button><a class="block print:hidden" href="{{ route('account.permissions.index') }}">Back to requests</a></section></x-layouts.public>
